document.addEventListener("DOMContentLoaded",()=>{fetch("data-base/data.json").then(e=>e.json()).then(e=>{const t=document.getElementById("personName"),n=document.getElementById("lastName");t&&(t.textContent=e.firstName),n&&(n.textContent=e.lastName),function(e,t,n="#ffca05"){const o=document.getElementById(t);o&&(o.innerHTML="",e.forEach(e=>{const t=document.createElement("div");t.classList.add("EXPERTISE"),t.innerHTML=`\n                        <label>${e.name}</label>\n                        <input type="range" class="slider" value="${e.value}">\n                    `;const a=t.querySelector(".slider");a.disabled=!0,a.style.background=`linear-gradient(to right, ${n} 0%, ${n} ${e.value}%, #5d5d6a ${e.value}%, #5d5d6a 100%)`,o.appendChild(t)}))}(e.expertise,"EXPERTISE","#ffca05");document.querySelectorAll(".experience-section").forEach(function(e){const t=e.querySelector(".text-5"),n=e.querySelector(".arrow"),o=e.querySelectorAll(".content-block");function a(){o.forEach(function(e){e.classList.toggle("show")}),n&&n.classList.toggle("rotated")}o.forEach(function(e){e.classList.remove("show")}),t.addEventListener("click",a),n&&n.addEventListener("click",a)})}).catch(e=>console.error("Error loading JSON:",e))});